class TeachersScreen extends StatefulWidget{const TeachersScreen({super.key});@override State<TeachersScreen> createState()=>_TeachersScreenState();}
class _TeachersScreenState extends State<TeachersScreen>{List teachers=[],students=[],subjects=[],supervisors=[];bool loading=true;static const fallback=['العربية','اللغة الإنجليزية','الرياضيات','العلوم','الدراسات الاجتماعية','Math','Science','English','Arabic','German','French','Spanish','Quran'];List<dynamic> list(dynamic x){if(x is List)return List<dynamic>.from(x);if(x is Map){final d=x['data'];if(d is List)return List<dynamic>.from(d);if(d is Map&&d['data'] is List)return List<dynamic>.from(d['data']);}return [];}int id(dynamic x)=>int.tryParse('${x['id']}')??0;void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));@override void initState(){super.initState();load();}
Future<void> load()async{if(mounted)setState(()=>loading=true);Object? primaryError;try{final r=await ApiService.get('teachers');if(mounted)setState(()=>teachers=list(r));}catch(e){primaryError=e;}try{final r=await ApiService.get('students');if(mounted)setState(()=>students=list(r));}catch(_){ }try{final r=await ApiService.get('subjects');if(mounted)setState(()=>subjects=list(r));}catch(_){if(mounted)setState(()=>subjects=fallback);}try{final r=await ApiService.get('supervisors');if(mounted)setState(()=>supervisors=list(r));}catch(_){ }if(mounted){setState(()=>loading=false);if(primaryError!=null)msg(primaryError!);}}
Future<void> edit(dynamic t)async{final n=TextEditingController(text:'${t['name']??''}'),p=TextEditingController(text:'${t['phone']??''}'),e=TextEditingController(text:'${t['email']??''}'),s=TextEditingController(text:'${t['specialization']??''}');final k=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('تعديل المدرس'),content:Form(key:k,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:n,decoration:const InputDecoration(labelText:'الاسم *'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:p,decoration:const InputDecoration(labelText:'الهاتف')),TextFormField(controller:e,decoration:const InputDecoration(labelText:'البريد')),TextFormField(controller:s,decoration:const InputDecoration(labelText:'التخصص'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(k.currentState!.validate())Navigator.pop(d,true);},child:const Text('حفظ'))]));if(ok==true){try{await ApiService.put('teachers/${id(t)}',{'name':n.text.trim(),'phone':p.text.trim(),'email':e.text.trim(),'specialization':s.text.trim()});await load();}catch(e){msg(e);}}for(final c in[n,p,e,s])c.dispose();}
Future<void> remove(dynamic t)async{final ok=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('حذف المدرس'),content:Text('حذف ${t['name']??''}؟'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('teachers/${id(t)}');await load();}catch(e){msg(e);}}}
