Future<void> details(int teacherId)async{try{final r=await ApiService.get('teachers/$teacherId');final d=Map<String,dynamic>.from(r['data'] is Map?r['data']:r);if(!mounted)return;final sl=list(d['students']),a=list(d['assignments']),pl=list(d['private_lessons']),gl=list(d['group_lessons']);await showDialog(context:context,builder:(dc)=>AlertDialog(title:Text('${d['teacher']?['name']??'المدرس'}'),content:SizedBox(width:560,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('الطلاب المرتبطون (${sl.length})',style:const TextStyle(fontWeight:FontWeight.bold)),if(sl.isEmpty)const Text('لا يوجد طلاب مرتبطون.'),...sl.map((s)=>ListTile(dense:true,leading:const Icon(Icons.person),title:Text('${s['name']??''}'),subtitle:Text('${s['pivot']?['subject']??''}')),),const Divider(),Text('العلاقات والأسعار: ${a.length}'),Text('الحصص الخاصة: ${pl.length}'),Text('حصص الجروب: ${gl.length}'),Text('المستحق: ${d['due']??0}'),Text('المدفوع: ${d['paid']??0}'),Text('المتبقي: ${d['remaining']??0}')])),),actions:[TextButton(onPressed:()=>Navigator.pop(dc),child:const Text('إغلاق'))]));}catch(e){msg(e);}}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المدرسون'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:add,backgroundColor:AppColors.red,icon:const Icon(Icons.person_add),label:const Text('إضافة مدرس')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,90),children:[Card(child:Padding(padding:const EdgeInsets.all(14),child:const Text('أضف المدرس، ثم افتح المدرس لرؤية الطلاب المرتبطين به فعليًا والحصص والمستحقات.'))),if(teachers.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Center(child:Text('لا يوجد مدرسون.'))),...teachers.map((t)=>Card(child:ListTile(onTap:()=>details(id(t)),leading:const CircleAvatar(child:Icon(Icons.school)),title:Text('${t['name']??''}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${t['phone']??t['email']??''}'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>edit(t),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(t),icon:const Icon(Icons.delete))]))))])));}
